328	func (s *Server) hookError(w http.ResponseWriter, err error) {
329		switch {
330		case errors.Is(err, webhooks.ErrInvalidURL):
331			writeError(w, http.StatusUnprocessableEntity, "invalid_url", err.Error())
332		case errors.Is(err, webhooks.ErrInvalidEvents):
333			writeError(w, http.StatusUnprocessableEntity, "invalid_events", err.Error())
334		default:
335			s.storeError(w, err)
336		}
337	}
