343	// createEndpoint adds an endpoint: {"url": ..., "events": [...]}. The answer includes the signing secret.
344	func (s *Server) createEndpoint(w http.ResponseWriter, r *http.Request, p auth.Principal) {
345		var in struct {
346			URL    string   `json:"url"`
347			Events []string `json:"events"`
348		}
349		if !decode(w, r, &in) {
350			return
351		}
352		if err := s.hooks.CheckURL(r.Context(), in.URL); err != nil {
353			s.hookError(w, err)
354			return
355		}
356		if err := webhooks.CheckEvents(in.Events); err != nil {
357			s.hookError(w, err)
358			return
359		}
360		ep, err := s.store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: p.OrgID, URL: in.URL, Events: in.Events, Secret: webhooks.NewSecret(), Enabled: true}, s.clock.Now())
361		if err != nil {
362			s.storeError(w, err)
363			return
364		}
365		writeJSON(w, http.StatusCreated, ep)
366	}
