377	func (s *Server) updateEndpoint(w http.ResponseWriter, r *http.Request, p auth.Principal) {
378		var in struct {
379			URL     *string   `json:"url"`
380			Events  *[]string `json:"events"`
381			Enabled *bool     `json:"enabled"`
382		}
383		if !decode(w, r, &in) {
384			return
385		}
386		if in.URL != nil {
387			if err := s.hooks.CheckURL(r.Context(), *in.URL); err != nil {
388				s.hookError(w, err)
389				return
390			}
391		}
392		if in.Events != nil {
393			if err := webhooks.CheckEvents(*in.Events); err != nil {
394				s.hookError(w, err)
395				return
396			}
397		}
398		ep, err := s.store.UpdateWebhookEndpoint(p.OrgID, r.PathValue("id"), func(ep *store.WebhookEndpoint) error {
399			if in.URL != nil {
400				ep.URL = *in.URL
401			}
402			if in.Events != nil {
403				ep.Events = *in.Events
404			}
405			if in.Enabled != nil {
406				ep.Enabled = *in.Enabled
407				if ep.Enabled {
408					ep.DisabledReason = ""
409				}
410			}
411			return nil
412		})
413		if err != nil {
414			s.storeError(w, err)
415			return
416		}
417		writeJSON(w, http.StatusOK, ep)
418	}
