457	package store
458	
459	import (
460		"encoding/json"
461		"sort"
462		"time"
463	)
464	
465	// CreateWebhookEndpoint stores an endpoint. The caller checks its URL and sets its secret.
466	func (s *Store) CreateWebhookEndpoint(ep WebhookEndpoint, now time.Time) (WebhookEndpoint, error) {
467		if len(ep.Events) == 0 {
468			return WebhookEndpoint{}, invalid("an endpoint needs at least one event type")
469		}
470		s.mu.Lock()
471		defer s.mu.Unlock()
472		if _, ok := s.orgs[ep.OrgID]; !ok {
473			return WebhookEndpoint{}, ErrNotFound
474		}
475		ep.ID = s.newID("we")
476		ep.CreatedAt = now.UTC()
477		ep.Events = append([]string(nil), ep.Events...)
478		s.endpoints[ep.ID] = ep
479		return copyEndpoint(ep), nil
480	}
481	
482	// WebhookEndpoint returns one of an organization's endpoints.
483	func (s *Store) WebhookEndpoint(orgID, id string) (WebhookEndpoint, bool) {
484		s.mu.Lock()
485		defer s.mu.Unlock()
486		ep, ok := s.endpoints[id]
487		if !ok || ep.OrgID != orgID {
488			return WebhookEndpoint{}, false
489		}
490		return copyEndpoint(ep), true
491	}
492	
493	// WebhookEndpoints returns an organization's endpoints, oldest first.
494	func (s *Store) WebhookEndpoints(orgID string) []WebhookEndpoint {
495		s.mu.Lock()
496		defer s.mu.Unlock()
497		out := []WebhookEndpoint{}
498		for _, ep := range s.endpoints {
499			if ep.OrgID == orgID {
500				out = append(out, copyEndpoint(ep))
501			}
502		}
503		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
504		return out
505	}
506	
507	// UpdateWebhookEndpoint changes an endpoint with f, which may refuse with an error.
508	func (s *Store) UpdateWebhookEndpoint(orgID, id string, f func(*WebhookEndpoint) error) (WebhookEndpoint, error) {
509		s.mu.Lock()
510		defer s.mu.Unlock()
511		old, ok := s.endpoints[id]
512		if !ok || old.OrgID != orgID {
513			return WebhookEndpoint{}, ErrNotFound
514		}
515		ep := copyEndpoint(old)
516		if err := f(&ep); err != nil {
517			return WebhookEndpoint{}, err
518		}
519		ep.ID, ep.OrgID, ep.CreatedAt = old.ID, old.OrgID, old.CreatedAt
520		if len(ep.Events) == 0 {
521			return WebhookEndpoint{}, invalid("an endpoint needs at least one event type")
522		}
523		s.endpoints[id] = copyEndpoint(ep)
524		return copyEndpoint(ep), nil
525	}
526	
527	// DeleteWebhookEndpoint removes an endpoint and its pending deliveries.
528	func (s *Store) DeleteWebhookEndpoint(id string) error {
529		s.mu.Lock()
530		defer s.mu.Unlock()
531		if _, ok := s.endpoints[id]; !ok {
532			return ErrNotFound
533		}
534		delete(s.endpoints, id)
535		for did, d := range s.delivs {
536			if d.EndpointID == id && d.Status == DeliveryPending {
537				delete(s.delivs, did)
538			}
539		}
540		return nil
541	}
542	
543	func copyEndpoint(ep WebhookEndpoint) WebhookEndpoint {
544		ep.Events = append([]string(nil), ep.Events...)
545		return ep
546	}
547	
548	// AddEvent records an event.
549	func (s *Store) AddEvent(orgID, typ string, data json.RawMessage, now time.Time) (Event, error) {
550		s.mu.Lock()
551		defer s.mu.Unlock()
552		if _, ok := s.orgs[orgID]; !ok {
553			return Event{}, ErrNotFound
554		}
555		e := Event{ID: s.newID("evt"), OrgID: orgID, Type: typ, Data: append(json.RawMessage(nil), data...), CreatedAt: now.UTC()}
556		s.events[e.ID] = e
557		return e, nil
558	}
559	
560	// Event returns one of an organization's events.
561	func (s *Store) Event(orgID, id string) (Event, bool) {
562		s.mu.Lock()
563		defer s.mu.Unlock()
564		e, ok := s.events[id]
565		if !ok || e.OrgID != orgID {
566			return Event{}, false
567		}
568		return e, true
569	}
570	
571	// EventByID returns an event of any organization (the webhook sender).
572	func (s *Store) EventByID(id string) (Event, bool) {
573		s.mu.Lock()
574		defer s.mu.Unlock()
575		e, ok := s.events[id]
576		return e, ok
577	}
578	
579	// Events returns an organization's events, oldest first, only those of one type when typ is set.
580	func (s *Store) Events(orgID, typ string) []Event {
581		s.mu.Lock()
582		defer s.mu.Unlock()
583		out := []Event{}
584		for _, e := range s.events {
585			if e.OrgID == orgID && (typ == "" || e.Type == typ) {
586				out = append(out, e)
587			}
588		}
589		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
590		return out
591	}
592	
593	// CreateDelivery queues an event for an endpoint.
594	func (s *Store) CreateDelivery(d Delivery, now time.Time) (Delivery, error) {
595		s.mu.Lock()
596		defer s.mu.Unlock()
597		ep, ok := s.endpoints[d.EndpointID]
598		if !ok || ep.OrgID != d.OrgID {
599			return Delivery{}, ErrNotFound
600		}
601		if e, ok := s.events[d.EventID]; !ok || e.OrgID != d.OrgID {
602			return Delivery{}, ErrNotFound
603		}
604		d.ID = s.newID("del")
605		d.CreatedAt = now.UTC()
606		if d.Status == "" {
607			d.Status = DeliveryPending
608		}
609		s.delivs[d.ID] = copyDelivery(d)
610		return copyDelivery(d), nil
611	}
612	
613	// Delivery returns a delivery of any organization (the webhook sender).
614	func (s *Store) Delivery(id string) (Delivery, bool) {
615		s.mu.Lock()
616		defer s.mu.Unlock()
617		d, ok := s.delivs[id]
618		return copyDelivery(d), ok
619	}
620	
621	// Deliveries returns an organization's deliveries to one endpoint, oldest first.
622	func (s *Store) Deliveries(orgID, endpointID string) []Delivery {
623		s.mu.Lock()
624		defer s.mu.Unlock()
625		out := []Delivery{}
626		for _, d := range s.delivs {
627			if d.OrgID == orgID && d.EndpointID == endpointID {
628				out = append(out, copyDelivery(d))
629			}
630		}
631		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
632		return out
633	}
634	
635	// DueDeliveries returns the pending deliveries of every organization whose next attempt is due by now, oldest first.
636	func (s *Store) DueDeliveries(now time.Time) []Delivery {
637		s.mu.Lock()
638		defer s.mu.Unlock()
639		out := []Delivery{}
640		for _, d := range s.delivs {
641			if d.Status == DeliveryPending && d.NextAttemptAt != nil && !d.NextAttemptAt.After(now) {
642				out = append(out, copyDelivery(d))
643			}
644		}
645		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
646		return out
647	}
648	
649	// UpdateDelivery changes a delivery with f.
650	func (s *Store) UpdateDelivery(id string, f func(*Delivery) error) (Delivery, error) {
651		s.mu.Lock()
652		defer s.mu.Unlock()
653		old, ok := s.delivs[id]
654		if !ok {
655			return Delivery{}, ErrNotFound
656		}
657		d := copyDelivery(old)
658		if err := f(&d); err != nil {
659			return Delivery{}, err
660		}
661		d.ID, d.OrgID, d.EndpointID, d.EventID, d.CreatedAt = old.ID, old.OrgID, old.EndpointID, old.EventID, old.CreatedAt
662		s.delivs[id] = copyDelivery(d)
663		return copyDelivery(d), nil
664	}
665	
666	func copyDelivery(d Delivery) Delivery {
667		for _, p := range []**time.Time{&d.NextAttemptAt, &d.LastAttemptAt} {
668			if *p != nil {
669				t := **p
670				*p = &t
671			}
672		}
673		return d
674	}
