939	// DeliveryStatus is a webhook delivery's state.
940	type DeliveryStatus string
941	
942	// Delivery states.
943	const (
944		DeliveryPending   DeliveryStatus = "pending"
945		DeliverySucceeded DeliveryStatus = "succeeded"
946		DeliveryFailed    DeliveryStatus = "failed"
947	)
948	
949	// Delivery is the sending of one event to one endpoint.
950	type Delivery struct {
951		ID             string         `json:"id"`
952		OrgID          string         `json:"org_id"`
953		EndpointID     string         `json:"endpoint_id"`
954		EventID        string         `json:"event_id"`
955		Status         DeliveryStatus `json:"status"`
956		Attempts       int            `json:"attempts"`
957		NextAttemptAt  *time.Time     `json:"next_attempt_at,omitempty"`
958		LastAttemptAt  *time.Time     `json:"last_attempt_at,omitempty"`
959		ResponseStatus int            `json:"response_status,omitempty"`
960		Error          string         `json:"error,omitempty"`
961		CreatedAt      time.Time      `json:"created_at"`
962	}
