func TestSignatureHeader(t *testing.T) {
	now := apitest.Start
	body := []byte(`{"id":"evt_1"}`)
	ts := strconv.FormatInt(now.Unix(), 10)
	sig := func(secret string) string {
		return webhooks.Sign(secret, []byte(ts+"."+string(body)))
	}
	got := webhooks.SignatureHeader([]string{"whsec_new", "whsec_old"}, now, body)
