}

func TestVerify(t *testing.T) {
	now := apitest.Start
	body := []byte(`{"id":"evt_1","type":"customer.created"}`)
	ts := now.Unix()
	header := func(at time.Time, secrets ...string) string {
		return webhooks.SignatureHeader(secrets, at, body)
	}
	ok := func(name, h string, secrets []string, tol time.Duration, at time.Time) {
		t.Helper()
		if err := webhooks.Verify(body, h, secrets, tol, at); err != nil {
			t.Errorf("%s: Verify = %v", name, err)
		}
	}
	fail := func(name, h string, payload []byte, secrets []string, tol time.Duration, at time.Time, want error) {
		t.Helper()
		if err := webhooks.Verify(payload, h, secrets, tol, at); !errors.Is(err, want) {
			t.Errorf("%s: Verify = %v, want %v", name, err, want)
		}
	}

	ok("current secret", header(now, "whsec_a"), []string{"whsec_a"}, 0, now)
	ok("any listed secret", header(now, "whsec_a"), []string{"whsec_x", "whsec_a"}, 0, now)
	ok("second v1 entry", header(now, "whsec_old", "whsec_new"), []string{"whsec_new"}, 0, now)
	ok("second secret of the list", header(now, "whsec_old"), []string{"whsec_new", "whsec_old"}, 0, now)
	ok("default tolerance, past edge", header(now.Add(-5*time.Minute), "whsec_a"), []string{"whsec_a"}, 0, now)
	ok("default tolerance, future edge", header(now.Add(5*time.Minute), "whsec_a"), []string{"whsec_a"}, 0, now)
	ok("explicit tolerance", header(now.Add(-time.Minute), "whsec_a"), []string{"whsec_a"}, time.Minute, now)
	ok("negative tolerance means the default", header(now.Add(-time.Minute), "whsec_a"), []string{"whsec_a"}, -time.Second, now)

	// The header format: keys in any order, spaces around pairs, unknown keys ignored.
	sig := webhooks.Sign("whsec_a", []byte(fmt.Sprintf("%d.%s", ts, body)))
	ok("reordered, spaced, v0", fmt.Sprintf(" v0=ignored , v1=%s ,t=%d", sig, ts), []string{"whsec_a"}, 0, now)

	fail("empty header", "", body, []string{"whsec_a"}, 0, now, webhooks.ErrMalformedHeader)
	fail("blank header", "  ", body, []string{"whsec_a"}, 0, now, webhooks.ErrMalformedHeader)
	fail("pair without =", fmt.Sprintf("t=%d,v1", ts), body, []string{"whsec_a"}, 0, now, webhooks.ErrMalformedHeader)
	fail("empty pair", fmt.Sprintf("t=%d,,v1=%s", ts, sig), body, []string{"whsec_a"}, 0, now, webhooks.ErrMalformedHeader)
	fail("timestamp not an integer", "t=yesterday,v1="+sig, body, []string{"whsec_a"}, 0, now, webhooks.ErrMalformedHeader)
	fail("timestamp with a fraction", fmt.Sprintf("t=%d.5,v1=%s", ts, sig), body, []string{"whsec_a"}, 0, now, webhooks.ErrMalformedHeader)
	fail("no timestamp", "v1="+sig, body, []string{"whsec_a"}, 0, now, webhooks.ErrNoTimestamp)
	fail("timestamp too old", header(now.Add(-301*time.Second), "whsec_a"), body, []string{"whsec_a"}, 0, now, webhooks.ErrTimestampTolerance)
	fail("timestamp too new", header(now.Add(301*time.Second), "whsec_a"), body, []string{"whsec_a"}, 0, now, webhooks.ErrTimestampTolerance)
	fail("timestamp far in the future", fmt.Sprintf("t=%d,v1=%s", int64(1<<62), sig), body, []string{"whsec_a"}, 0, now, webhooks.ErrTimestampTolerance)
	fail("timestamp at the lowest int64", "t=-9223372036854775808,v1="+sig, body, []string{"whsec_a"}, 0, now, webhooks.ErrTimestampTolerance)
	fail("no v1", fmt.Sprintf("t=%d,v0=%s", ts, sig), body, []string{"whsec_a"}, 0, now, webhooks.ErrNoSignature)
	fail("wrong secret", header(now, "whsec_b"), body, []string{"whsec_a"}, 0, now, webhooks.ErrSignatureMismatch)
	fail("no secrets", header(now, "whsec_a"), body, nil, 0, now, webhooks.ErrSignatureMismatch)
	fail("changed payload", header(now, "whsec_a"), []byte(`{"id":"evt_2"}`), []string{"whsec_a"}, 0, now, webhooks.ErrSignatureMismatch)
	fail("changed timestamp", fmt.Sprintf("t=%d,v1=%s", ts-1, sig), body, []string{"whsec_a"}, 0, now, webhooks.ErrSignatureMismatch)

	// Checked in order: a bad timestamp is reported before a missing signature.
	fail("tolerance before no signature", fmt.Sprintf("t=%d", ts-3600), body, []string{"whsec_a"}, 0, now, webhooks.ErrTimestampTolerance)
	fail("malformed before no timestamp", "v1=x,oops", body, []string{"whsec_a"}, 0, now, webhooks.ErrMalformedHeader)
}

func TestSecretRotation(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	ep, _ := e.Store.CreateWebhookEndpoint(store.WebhookEndpoint{OrgID: e.Acme.ID, URL: "https://hooks.acme.example/all", Events: []string{"*"}, Secret: "whsec_1", Enabled: true}, e.Clock.Now())

	// Before any rotation a delivery carries one signature.
	header, body := publishAndSend(t, e)
	if strings.Count(header, ",v1=") != 1 || webhooks.Verify(body, header, []string{"whsec_1"}, 0, e.Clock.Now()) != nil {
